@php($f = fn (int $v) => number_format($v / 100, 2, ',', '.')) @php($c = $invoice->currencySymbol()) @php($vat = ($company->is_vat_obligor ?? true) || $invoice->tax_total > 0)
<!DOCTYPE html><html lang="sr"><head><meta charset="utf-8"><title>Račun {{ $invoice->invoice_number }}</title><style>@page{margin:0}*{box-sizing:border-box}body{margin:0;color:#3b2f20;font-family:DejaVu Sans Mono,monospace;font-size:7.6pt}.p{padding:13mm 15mm 18mm}.command{padding:8mm;border:1px solid #f3cf9d;background:#fffaf2}.amber{color:#d97706}.h{margin:5px 0;font-size:18pt;font-weight:bold}.t,.items,.sum{width:100%;border-collapse:collapse}.t{margin:6mm 0}.t>tbody>tr>td{width:50%;padding:6px 8px;vertical-align:top;border-bottom:1px dashed #e8bd7e}.client{margin:4px 0;font-size:10pt;font-weight:bold}.mute{color:#8a765a;line-height:1.45}.items th{padding:6px 4px;background:#fff1dc;color:#b45309;font-size:6pt;text-align:left}.items td{padding:7px 4px;border-bottom:1px dashed #efd7b3;vertical-align:top}.r{text-align:right;white-space:nowrap}.ct{text-align:center}.sum{width:42%;margin:7mm 0 0 auto;border:1px solid #edbd7a}.sum td{padding:6px;border-top:1px solid #f4d5a7}.sum td:last-child{text-align:right;font-weight:bold}.total td{background:#d97706;color:#fff;font-size:11pt}.box{margin-top:7mm;padding:7px 9px;background:#fff8ed;border:1px solid #f1c68d;white-space:pre-line}.foot{position:fixed;right:15mm;bottom:7mm;left:15mm;color:#b09978;font-size:6pt}</style></head><body><div class="p"><div class="command"><div class="amber">račun@lokalno:~$ izdavanje --potvrđeno</div><div class="h">{{ $company->name }}</div><div class="mute">{{ $company->address }} · {{ $company->zip }} {{ $company->city }}@if($company->identification_number)<br>JIB: {{ $company->identification_number }}@endif</div><div class="amber" style="margin-top:6px">izlaz: {{ $invoice->invoice_number }} / {{ $invoice->date?->format('d.m.Y.') }}</div></div><table class="t"><tr><td><div class="amber">[ kupac ]</div><div class="client">{{ $invoice->client?->name ?? '—' }}</div><div class="mute">{{ $invoice->client?->address }}<br>{{ $invoice->client?->zip }} {{ $invoice->client?->city }}</div></td><td><div class="amber">[ parametri ]</div><div class="mute">rok: <strong>{{ $invoice->due_date?->format('d.m.Y.') ?? '—' }}</strong><br>plaćanje: <strong>{{ $invoice->payment_type?->label() ?? '—' }}</strong><br>valuta: <strong>{{ $invoice->currency }}</strong></div></td></tr></table><table class="items"><thead><tr><th>#</th><th style="width:43%">stavka</th><th class="ct">jm</th><th class="r">kol.</th><th class="r">cijena</th>@if($vat)<th class="r">pdv</th>@endif<th class="r">iznos</th></tr></thead><tbody>@foreach($invoice->items as $i=>$item) @php($q=max(1,(int)$item->quantity))<tr><td>{{ $i+1 }}</td><td><strong>{{ $item->name }}</strong>@if($item->description)<div class="mute">{{ $item->description }}</div>@endif</td><td class="ct">{{ $item->unit?->value }}</td><td class="r">{{ $item->quantity }}</td><td class="r">{{ $f((int)round($item->total/$q)) }} {{ $c }}</td>@if($vat)<td class="r">{{ number_format($item->tax_rate/100,2,',','.') }}%</td>@endif<td class="r"><strong>{{ $f($item->total) }} {{ $c }}</strong></td></tr>@endforeach</tbody></table><table class="sum"><tr><td>osnovica</td><td>{{ $f($invoice->subtotal) }} {{ $c }}</td></tr>@if($vat)<tr><td>pdv</td><td>{{ $f($invoice->tax_total) }} {{ $c }}</td></tr>@endif<tr class="total"><td>ukupno</td><td>{{ $f($invoice->total) }} {{ $c }}</td></tr></table>@if($invoice->notes)<div class="box"><span class="amber"># napomena</span><br>{{ $invoice->notes }}</div>@endif<div class="box"><span class="amber"># plaćanje</span><br>@forelse($bankAccounts as $a)<strong>{{ $a->bank_name }}</strong> · {{ $a->account_number }}<br>@empty<span class="mute">Podaci za bankovni račun nisu uneseni.</span>@endforelse</div></div><div class="foot">shell / završeno bez greške / {{ $invoice->invoice_number }}</div></body></html>
